  {"type": "tool_use", "id": "toolu_01", "name": "find_order", "input": {"id": "A-42"}}]}

// 3) Your app runs it and replies in a user message
{"role": "user", "content": [
  {"type": "tool_result", "tool_use_id": "toolu_01", "content": "Order A-42: shipped"}]}

const maxSteps = 8;
for (let step = 0; step < maxSteps; step++) {
  const action = await decide(context);
  if (action.type === "finish") break;
  context = await runAndObserve(action);
}

function validate(input) {
  if (typeof input.id !== "string" || !/^[A-Z0-9-]{1,20}$/.test(input.id)) {
    throw new Error("Invalid identifier");
  }
  return input.id;
}
